import math
from collections import Counter
nodes=[(u,v) for u in (0,1) for v in (0,1)]
def js(p,q):
 m={k:(p.get(k,0)+q.get(k,0))/2 for k in p.keys()|q.keys()}
 return sum(t*math.log(t/m[k])/2 for d in (p,q) for k,t in d.items() if t)
for name,s in [('s=v',lambda h:h[1]),('s=u',lambda h:h[0])]:
 groups=[[h for h in nodes if s(h)==g] for g in (0,1)]
 p,q=[{h:1/len(group) for h in group} for group in groups]
 dp=abs(sum(h[0] for h in groups[0])/len(groups[0])-sum(h[0] for h in groups[1])/len(groups[1]))
 print(name,'JS(h|s):',round(js(p,q),6),'DP for prediction u:',dp)
PY"
